effect.shader:
// Halftone / Dot Screen (ported from Shadertoy and adapted for Alight Motion)
// Ruofei Du references: https://www.shadertoy.com/view/4sBBDK, https://www.shadertoy.com/view/lsSfWV

const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

float greyScale(vec3 c){ return dot(c, LUMA); }

mat2 rot(float a){ float s=sin(a), c=cos(a); return mat2(c,-s,s,c); }

// Simple 3x3 box smooth of luminance controlled by smoothSource
float smoothLum(vec2 uv){
  if(smoothSource <= 0.0) return greyScale(texture2DCv(inputImg.texture, uv).rgb);
  vec2 texel = 1.0 / getTexSize(inputImg.size);
  float r = clamp(smoothSource, 0.0, 2.0);
  vec2 o = texel * r;
  float acc = 0.0; float w = 0.0;
  for(int j=-1;j<=1;j++){
    for(int i=-1;i<=1;i++){
      float ww = (i==0 && j==0) ? 2.0 : 1.0;
      acc += greyScale(texture2DCv(inputImg.texture, uv + vec2(i,j)*o).rgb) * ww;
      w += ww;
    }
  }
  return acc / max(w, 1.0);
}

// Dot screen pattern (returns roughly -4..+4 like the Shadertoy version*4)
float dotScreen(vec2 uv, float angle, float scale, float relWidth){
  // shift in pixels -> UV
  vec2 shiftPx = vec2(shiftX, -shiftY);
  vec2 uvShift = uv + shiftPx / acScreenSize;
  // pixel space centered
  vec2 p = (uvShift - 0.5) * acScreenSize;
  // anisotropic scaling
  vec2 q = rot(angle) * p;
  q.x *= relWidth;
  q *= scale;
  return (sin(q.x) * sin(q.y)) * 4.0;
}

void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float grey = smoothLum(uv);

  // Map UI parameters
  float ang = radians(dotsAngle);
  // Frequency maps to scale (empirical mapping for useful range)
  // Higher frequency -> denser dots -> larger multiplier
  float scale = dotsFrequency * 0.06; // tuneable mapping

  float pat = dotScreen(uv, ang, scale, dotsRelWidth);

  // Original Shadertoy combination
  float v = grey * 10.0 - 5.0 + pat + dotsLighten;

  // Convert to 0..1 mask with adjustable sharpness
  float s = max(dotsSharpness, 0.0001);
  float m = smoothstep(-s, s, v);

  // Dots mode: 0 -> Black dots, 1 -> White dots (swap mask)
  if(int(dotsMode)==1) m = 1.0 - m;

  // Map mask to two colors
  vec3 c0 = color0.rgb;
  vec3 c1 = color1.rgb;
  vec3 halftone = mix(c0, c1, m);

  // Preserve original alpha and allow overall alpha control
  float a = src.a * alpha;
  gl_FragColor = vec4(halftone, 1.0) * a;
}
